    auto placed=place(first);app::FtnOutboundJob payload;payload.id=id(next++);payload.operation=first.operation;payload.network="TEST";payload.link="DOWN";payload.kind=app::FtnOutboundKind::payload;payload.file={first.filename,first.payload.bytes,1700000000};payload.digest=first.payload.sha256;auto tic=payload;tic.id=id(next++);tic.ordinal=1;tic.kind=app::FtnOutboundKind::tic;tic.file={"forward.tic",100,1700000000};tic.digest=publication_hash(next++);const std::vector<app::FtnOutboundJob> jobs{payload,tic};
